import java.util.*;

public class Main {
    String fractionToDecimal(long numerator, long denominator) {
        if (numerator == 0) {
            return "0";
        }
        String sign = (numerator < 0) != (denominator < 0) ? "-" : "";
        numerator = Math.abs(numerator);
        denominator = Math.abs(denominator);
        long integerPart = numerator / denominator;
        long remainder = numerator % denominator;
        if (remainder == 0) {
            return sign + integerPart;                            // the division ends evenly, no decimal needed
        }
        List<Character> digits = new ArrayList<>();
        List<Long> seenRemainders = new ArrayList<>();          // every remainder seen so far, in the order seen
        while (remainder != 0) {
            int position = -1;
            for (int idx = 0; idx < seenRemainders.size(); idx++) {  // scan back through every remainder seen before
                if (seenRemainders.get(idx) == remainder) {
                    position = idx;
                    break;
                }
            }
            if (position != -1) {
                digits.add(position, '(');                            // the repeating part starts right here
                digits.add(')');
                break;
            }
            seenRemainders.add(remainder);
            remainder *= 10;
            digits.add((char) ('0' + remainder / denominator));
            remainder %= denominator;
        }
        StringBuilder sb = new StringBuilder();
        for (char c : digits) {
            sb.append(c);
        }
        return sign + integerPart + "." + sb;
    }

    public static void main(String[] args) {
        long numerator = 4, denominator = 333;
        Main solution = new Main();
        System.out.println(solution.fractionToDecimal(numerator, denominator));
    }
}

