    }
    vector<char> digits;
    vector<long long> seenRemainders;                            // every remainder seen so far, in the order seen
    while (remainder != 0) {
        int position = -1;
        for (int idx = 0; idx < (int) seenRemainders.size(); idx++) {  // scan back through every remainder seen
            if (seenRemainders[idx] == remainder) {
                position = idx;
                break;
            }
        }
        if (position != -1) {
            digits.insert(digits.begin() + position, '(');            // the repeating part starts right here
            digits.push_back(')');
            break;
        }
        seenRemainders.push_back(remainder);
        remainder *= 10;
        digits.push_back('0' + remainder / denominator);
        remainder %= denominator;
    }
    return sign + to_string(integerPart) + "." + string(digits.begin(), digits.end());
}

